contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will test one sequence: addToBalance then attempt withdrawBalance.
    // Parameters:
    // - uint addAmt: amount of wei to send with addToBalance
    // - bool tryWithdraw: whether to call withdrawBalance after adding
    // The test will check that addToBalance increases c.getBalance(this) by addAmt
    // and increases address(c).balance by addAmt. If withdraw is attempted, then
    // either it succeeds and sets c.getBalance(this)==0 and address(c).balance decreased by that amount,
    // or it reverts and balances remain as after add.

    function run(uint addAmt, bool tryWithdraw) public payable {
        require(address(this).balance >= addAmt, "insufficient balance to fund addAmt");
        // read before-values
        uint beforeStored = c.getBalance(address(this));
        uint beforeContractBalance = address(c).balance;

        // perform addToBalance with value addAmt
        c.addToBalance{value: addAmt}();

        // read after add
        uint afterStored = c.getBalance(address(this));
        uint afterContractBalance = address(c).balance;

        // basic invariant: stored and contract balance increased by exactly addAmt
        bool add_ok = (afterStored == beforeStored + addAmt) && (afterContractBalance == beforeContractBalance + addAmt);

        bool withdrew = false;
        bool withdrewReverted = false;
        uint afterWithdrawStored = afterStored;
        uint afterWithdrawContractBalance = afterContractBalance;

        if (tryWithdraw) {
            // attempt withdraw and observe whether it reverts
            try c.withdrawBalance() {
                withdrew = true;
            } catch {
                withdrewReverted = true;
            }
            // read final state
            afterWithdrawStored = c.getBalance(address(this));
            afterWithdrawContractBalance = address(c).balance;
        }

        // The general rule asserted below:
        // - add_ok must hold (addToBalance always updates stored balance and contract balance by the sent amount)
        // - If withdraw was attempted and it succeeded, then the stored balance must be zero and the contract balance decreased by the same amount that was recorded before withdraw (i.e., afterStored).
        // - If withdraw was attempted and it reverted, then stored and contract balances remain as after add.
        assert(
            add_ok && (
                !tryWithdraw || (
                    (withdrew && afterWithdrawStored == 0 && afterWithdrawContractBalance + afterStored == afterContractBalance) ||
                    (withdrewReverted && afterWithdrawStored == afterStored && afterWithdrawContractBalance == afterContractBalance)
                )
            )
        );
    }

    // receive to allow the contract to accept refunds/ether
    receive() external payable {}
}

