contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes two parameters: amount to add, and a flag whether to attempt withdraw after
    function run(uint256 amount, bool doWithdraw) public payable {
        require(address(this).balance >= amount);

        // read balances before
        uint256 beforeUser = c.getBalance(address(this));
        uint256 beforeContractBal = address(c).balance;

        // call addToBalance sending `amount` wei
        c.addToBalance{value: amount}();

        // read balances after add
        uint256 afterUser = c.getBalance(address(this));
        uint256 afterContractBal = address(c).balance;

        bool withdrewReverted = false;
        uint256 afterUserAfterWithdraw = afterUser;
        uint256 contractBalAfterWithdraw = afterContractBal;

        if (doWithdraw) {
            // try withdraw and record whether it reverted
            try c.withdrawBalance() {
                withdrewReverted = false;
                // on success, observe balances
                afterUserAfterWithdraw = c.getBalance(address(this));
                contractBalAfterWithdraw = address(c).balance;
            } catch {
                withdrewReverted = true;
                // if reverted, state should be unchanged from after-add
                afterUserAfterWithdraw = afterUser;
                contractBalAfterWithdraw = afterContractBal;
            }
        }

        // General property to assert:
        // 1) The add increased the recorded user balance by exactly amount.
        // 2) The contract's ether balance increased by exactly amount.
        // 3) If withdraw succeeded, then the user's recorded balance becomes 0 and the contract's balance decreased by the same amount that was recorded before withdraw.
        // 4) If withdraw reverted or not attempted, balances remain consistent (no change from after-add).
        assert(
            // add effect
            afterUser == beforeUser + amount
            && afterContractBal == beforeContractBal + amount
            && (
                // if we didn't attempt withdraw: balances remain as after-add
                (!doWithdraw) && (afterUserAfterWithdraw == afterUser) && (contractBalAfterWithdraw == afterContractBal)
                ||
                // if we attempted withdraw and it reverted: no state change
                (doWithdraw && withdrewReverted && (afterUserAfterWithdraw == afterUser) && (contractBalAfterWithdraw == afterContractBal))
                ||
                // if we attempted withdraw and it succeeded: user balance is zero and contract balance decreased by the prior user balance
                (doWithdraw && !withdrewReverted && (afterUserAfterWithdraw == 0) && (contractBalAfterWithdraw + afterUser == afterContractBal))
            )
        );
    }

    // receive to allow receiving funds when withdraw is called
    receive() external payable {}
}

