contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run: perform an optional deposit from this test contract to c, then attempt withdrawal
    // params: depositAmount is sent to addToBalance, and gaslessWithdraw indicates whether to call withdraw
    function run(uint depositAmount, bool doWithdraw) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        // Record contract balance and user balance before any operations
        uint beforeCbalance = address(c).balance;
        uint beforeUserBalance = c.getBalance(address(this));

        // If depositAmount > 0, call addToBalance sending that Ether
        if (depositAmount > 0) {
            c.addToBalance{value: depositAmount}();
        }

        // After deposit, record new values
        uint afterDepositCbalance = address(c).balance;
        uint afterDepositUserBalance = c.getBalance(address(this));

        // deposit must have increased both the contract balance and the user balance by the same amount
        // (This is a general observable expectation about addToBalance)
        assert(afterDepositCbalance - beforeCbalance == afterDepositUserBalance - beforeUserBalance);

        bool withdrewReverted;
        uint beforeWithdrawCbalance = address(c).balance;
        uint beforeWithdrawUserBalance = c.getBalance(address(this));

        if (doWithdraw) {
            // attempt withdrawal and catch revert
            try c.withdrawBalance() {
                withdrewReverted = false;
            } catch {
                withdrewReverted = true;
            }
        } else {
            withdrewReverted = true; // if we don't call withdraw, treat as reverted for the assertion below
        }

        uint afterWithdrawCbalance = address(c).balance;
        uint afterWithdrawUserBalance = c.getBalance(address(this));

        // Final invariant (single assert): If withdraw was attempted and did not revert,
        // then the user's recorded balance must be zero and the contract's balance must have decreased by exactly the user's prior recorded balance.
        assert(
            withdrewReverted || (
                afterWithdrawUserBalance == 0 && beforeWithdrawCbalance - afterWithdrawCbalance == beforeWithdrawUserBalance
            )
        );
    }

    // allow receiving Ether so this test contract can fund deposits
    receive() external payable {}
}

