        uint256 contractBalanceBeforeWithdraw = address(c).balance;
        // try withdraw depending on input flag
        if (doWithdraw) {
            try c.withdrawBalance() {
                withdrewReverted = false;
            } catch {
                withdrewReverted = true;
            }
        }

        uint256 contractBalanceAfter = address(c).balance;
        uint256 userBalanceAfter = c.getBalance(address(this));

        // General invariant: if withdrawal did not revert, the stored user balance for this caller must be zero
        // and the contract's Ether balance must have decreased by at least the previous stored amount (no duplication).
