        // unless the contract's balance also decreased accordingly.
        assert(
            // case: we didn't attempt withdraw -> nothing specific beyond earlier deposit checks (already asserted)
            (!doWithdraw) ||
            // case: attempted withdraw and it reverted -> either stored balance still equals amount or contract balance did not drop
            (withdrewReverted && (userBalanceAfter == afterUserBalance || contractBalanceAfter >= contractBalanceBeforeWithdraw)) ||
            // case: attempted withdraw and succeeded -> stored balance must be zero and contract balance decreased by at least the withdrawn amount
            (!withdrewReverted && userBalanceAfter == 0 && contractBalanceAfter + afterUserBalance <= contractBalanceBeforeWithdraw)
        );
